class Solution:
    def countRangeSum(self, nums: List[int], lower: int, upper: int) -> int:
        n = len(nums)
        pre = [0]
        for x in nums:
            pre.append(pre[-1] + x)
        ans = 0
        for j in range(1, n + 1):
            for i in range(j):
                if lower <= pre[j] - pre[i] <= upper:
                    ans += 1
        return ans

