        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + (long long)nums[i];
        for (int j = 1; j <= n; ++j)
            for (int i = 0; i < j; ++i)
                if (lower <= pre[j] - pre[i] && pre[j] - pre[i] <= upper) ++ans;
        return ans;
    }
};

