class Solution:
    def countRangeSum(self, nums: List[int], lower: int, upper: int) -> int:
        pre = [0]
        for x in nums:
            pre.append(pre[-1] + x)

        def sort_count(lo: int, hi: int) -> int:
            if hi - lo <= 1:
                return 0
            mid = (lo + hi) // 2
            cnt = sort_count(lo, mid) + sort_count(mid, hi)
            k = t = mid
            for i in range(lo, mid):
                while k < hi and pre[k] - pre[i] < lower:
                    k += 1
                while t < hi and pre[t] - pre[i] <= upper:
                    t += 1
                cnt += t - k
            merged = []
            i, j = lo, mid
            while i < mid and j < hi:
                if pre[i] <= pre[j]:
                    merged.append(pre[i])
                    i += 1
                else:
                    merged.append(pre[j])
                    j += 1
            merged.extend(pre[i:mid])
            merged.extend(pre[j:hi])
            pre[lo:hi] = merged
            return cnt

        return sort_count(0, len(pre))

