class Solution {
    long long lo_, hi_;

    int sortCount(vector<long long>& pre, int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = lo + (hi - lo) / 2;
        int cnt = sortCount(pre, lo, mid) + sortCount(pre, mid, hi);
        int k = mid, t = mid;
        for (int i = lo; i < mid; ++i) {
            while (k < hi && pre[k] - pre[i] < lo_) ++k;
            while (t < hi && pre[t] - pre[i] <= hi_) ++t;
            cnt += t - k;
        }
        inplace_merge(pre.begin() + lo, pre.begin() + mid, pre.begin() + hi);
        return cnt;
    }

public:
    int countRangeSum(vector<int>& nums, int lower, int upper) {
        int n = nums.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + (long long)nums[i];
        lo_ = lower; hi_ = upper;
        return sortCount(pre, 0, n + 1);
    }
};

