class Solution {
    private long lower, upper;

    private int sortCount(long[] pre, int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = (lo + hi) >>> 1;
        int cnt = sortCount(pre, lo, mid) + sortCount(pre, mid, hi);
        int k = mid, t = mid;
        for (int i = lo; i < mid; i++) {
            while (k < hi && pre[k] - pre[i] < lower) k++;
            while (t < hi && pre[t] - pre[i] <= upper) t++;
            cnt += t - k;
        }
        long[] tmp = new long[hi - lo];
        int i = lo, j = mid, p = 0;
        while (i < mid && j < hi) tmp[p++] = pre[i] <= pre[j] ? pre[i++] : pre[j++];
        while (i < mid) tmp[p++] = pre[i++];
        while (j < hi) tmp[p++] = pre[j++];
        System.arraycopy(tmp, 0, pre, lo, tmp.length);
        return cnt;
    }

    public int countRangeSum(int[] nums, int lower, int upper) {
        int n = nums.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        this.lower = lower;
        this.upper = upper;
        return sortCount(pre, 0, n + 1);
    }
}

