class Solution:
    def countRangeSum(self, nums: List[int], lower: int, upper: int) -> int:
        n = len(nums)
        pre = [0]
        for x in nums:
            pre.append(pre[-1] + x)
        vals = sorted({v for p in pre for v in (p, p - lower, p - upper)})
        rank = {v: i + 1 for i, v in enumerate(vals)}
        m = len(vals)
        tree = [0] * (m + 1)

        def update(i: int) -> None:
            while i <= m:
                tree[i] += 1
                i += i & (-i)

        def query(i: int) -> int:
            s = 0
            while i > 0:
                s += tree[i]
                i -= i & (-i)
            return s

        ans = 0
        for p in pre:
            ans += query(rank[p - lower]) - query(rank[p - upper] - 1)
            update(rank[p])
        return ans

