class Solution {
    vector<int> tree;

    void update(int i) {
        for (; i < (int)tree.size(); i += i & (-i)) tree[i]++;
    }

    int query(int i) {
        int s = 0;
        for (; i > 0; i -= i & (-i)) s += tree[i];
        return s;
    }

public:
    int countRangeSum(vector<int>& nums, int lower, int upper) {
        int n = nums.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + (long long)nums[i];
        vector<long long> vals;
        vals.reserve(pre.size() * 3);
        for (long long p : pre) { vals.push_back(p); vals.push_back(p - lower); vals.push_back(p - upper); }
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        auto rank = [&](long long v) {
            return (int)(lower_bound(vals.begin(), vals.end(), v) - vals.begin()) + 1;
        };
        tree.assign(vals.size() + 1, 0);
        int ans = 0;
        for (long long p : pre) {
            ans += query(rank(p - lower)) - query(rank(p - upper) - 1);
            update(rank(p));
        }
        return ans;
    }
};

