        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        TreeSet<Long> set = new TreeSet<>();
        for (long p : pre) { set.add(p); set.add(p - lower); set.add(p - upper); }
        Map<Long, Integer> rank = new HashMap<>();
        int idx = 1;
        for (long v : set) rank.put(v, idx++);
        bit = new long[rank.size() + 1];
        int ans = 0;
        for (long p : pre) {
            ans += query(rank.get(p - lower)) - query(rank.get(p - upper) - 1);
            update(rank.get(p));
        }
        return ans;
    }
}

