var countRangeSum = function(nums, lower, upper) {
    const n = nums.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    const vals = [...new Set(pre.flatMap(p => [p, p - lower, p - upper]))]
        .sort((a, b) => a - b);
    const rank = new Map(vals.map((v, i) => [v, i + 1]));
    const tree = new Array(vals.length + 1).fill(0);
    const update = i => { for (; i < tree.length; i += i & (-i)) tree[i]++; };
    const query = i => { let s = 0; for (; i > 0; i -= i & (-i)) s += tree[i]; return s; };
    let ans = 0;
    for (const p of pre) {
        ans += query(rank.get(p - lower)) - query(rank.get(p - upper) - 1);
        update(rank.get(p));
    }
    return ans;
};
